/**
 * Catalog source of a SID field in a SCENARIO's input_schema. A superset of the
 * module-param discriminator (`ModuleInputSource`): scenario input adds `roster`.
 *
 * The scenario schema travels as a raw map (the keeper does not project it through a
 * typed wire schema), so this type is declared here rather than generated — which is
 * also why it can carry a variant the module contract has no use for.
 *
 * Exactly one variant is active:
 *  - `incarnation_hosts` / `choir` — resolved against an EXISTING incarnation, so they
 *    need an incarnation context and are fetched through module form-prep;
 *  - `roster` — the souls an incarnation is being CREATED on (ADR-081). There is no
 *    incarnation to resolve against yet, so the catalog is the scoped souls list:
 *    free, online hosts inside the covens the form declares.
 */
export type ScenarioInputSource = ModuleInputSource & { roster?: boolean };

// input_schema — flat-map field→property (NOT a JSON-Schema wrapper `{type:'object',properties}`).
// Each property carries its own `required: boolean` (per-field, not a top-level array).
// UI renders simple types (string/integer/number/boolean) per-field; composite
// types (array/object/oneOf/...) → fallback to a JSON textarea.
// ADR-045 S4: pattern/format/source describe the module's UI form (SID-picker, validation).
export interface ScenarioInputSchemaProperty {
  type?: string;
  description?: string;
  required?: boolean;
  /** CEL predicate for required-ness (reactive, like show_when). Field is required when the expression is true. */
  required_when?: string;
  default?: unknown;
  enum?: unknown[];
  /** Regex constraint on the value (ADR-045). */
  pattern?: string;
  /** Semantic string format (sid/hostname/...). */
  format?: string;
  /** Catalog source for the SID-picker (ADR-045). */
  source?: ScenarioInputSource;
  /**
   * List item type (ADR-045 S8b). Present for type=array.
   * Contains a nested ScenarioInputSchemaProperty (recursively).
   * For type=map/object: the map's value type — with a scalar items.type
   * the UI renders a KEY->VALUE editor; without items -> JSON textarea.
   */
  items?: ScenarioInputSchemaProperty;
  /** Field is a large textarea rather than a single-line input (ADR-045 B3). */
  multiline?: boolean;
  /** Example value for the placeholder (ADR-045 B3). */
  example?: string;
  /** Marker for a normalized map type (type=map): scalar items.type -> KEY->VALUE editor. */
  isMap?: boolean;
  /**
   * NIM-243: the module still honors the parameter but it is on its way out.
   * A warning, never a gate — the field stays editable and is still submitted.
   * Carried here (rather than alongside the schema) so it survives
   * paramsToInputSchema, which builds properties from an explicit field list.
   */
  deprecated?: ModuleDeprecation;
  /**
   * Sub-fields of a typed object (NIM-72). Present for a single
   * type=object (AclUser add_user.user) and for items array-of-object.
   * Note: object-level `required` here is an array of required sub-field names
   * (JSON-Schema style), not a boolean; read via a cast.
   */
  properties?: Record<string, ScenarioInputSchemaProperty>;
  /**
   * type=object map (NIM-72): scalar value schema ({type:string}) -> MapEditor;
   * false — typed object (not a map); true/absent — degrade to JSON textarea.
   */
  additional_properties?: ScenarioInputSchemaProperty | boolean;
  /** Sub-object type name (AclUser...) — UI label. */
  'x-type'?: string;
  /**
   * NIM-76: marker for a directives-dictionary field. A truthy value (e.g. "redis") enables
   * inline validation + key typeahead against the service's directive catalog. We validate
   * ONLY marked fields (the redis_settings name is not hardcoded).
   */
  'x-directives'?: string;
  /**
   * NIM-72: field-level required-ness of a $type reference node. For object-$type the
   * `required` key is taken by the array of required children — "the field itself is required"
   * comes via this annotation, and the UI shows `*` based on it.
   */
  'x-required'?: boolean;
  [key: string]: unknown;
}
export type ScenarioInputSchema = Record<string, ScenarioInputSchemaProperty>;

