export interface ServiceScenarioInfo {
  name: string;
  // Backend returns `scenario/<name>/main.yml` — read-only, informational.
  path?: string;
  /** Discriminator: lifecycle (create/destroy/converge) | operational. */
  kind: 'lifecycle' | 'operational';
  /**
   * Runnable by an operator from the Run form (ADR-042, backend field).
   * create=true, destroy=false, operational=true.
   * UI filters by this field, not by hardcoded names.
   * Optional for backward compatibility: an old backend without the field -> fallback to runnableScenarios.
   */
  runnable?: boolean;
  /**
   * Starting scenario for incarnation creation (POST /v1/incarnations).
   * If true — the scenario is offered in the dropdown when creating an incarnation.
   * UI filters create scenarios by this flag (not by hardcoded names).
   */
  create?: boolean;
  description?: string;
  input_schema?: ScenarioInputSchema;
  /**
   * The create scenario composes the incarnation name from its `input:`
   * components instead of the operator typing one, so POST /v1/incarnations must
   * NOT carry `name` (the keeper refuses a request that does).
   *
   * A flag, not the template: the operator is shown the resulting name, not the
   * formula. The name itself comes from `incarnations.resolveName` — the keeper
   * composes, the form displays. Composing here instead would mean a second CEL
   * evaluator producing a different string from the same input, and under an
   * immutable name that is a different identity, arrived at silently.
   *
   * Optional for backward compatibility: an older keeper omits the field, and the
   * form then behaves as it did before — a name is typed.
   */
  composes_name?: boolean;
  /** Optional presentation layer: splits fields into sections with headings. */
  form?: ScenarioForm;
}
// Backend shape: `{ service, ref, scenarios: [...] }` (NOT `{ items: [...] }`).
export interface ServiceScenarioListReply {
  service?: string;
  ref?: string;
  scenarios: ServiceScenarioInfo[];
}

// GET /v1/services/{name}/directives[?ref=&version=] — catalog of allowed
// directive names (redis.conf) by Redis series. directives: series "major.minor" ->
// sorted names. Response is immutable per git-ref (ETag + Cache-Control: immutable);
// cached aggressively (staleTime: Infinity, keyed by service+ref). A service without a catalog
// -> directives:{} + 200. Endpoint is optional — UI graceful-degraded on 404/501.
export interface ServiceDirectivesReply {
  service?: string;
  ref?: string;
  sha1?: string;
  // Series ("8.2") -> sorted directive names; nullable per contract.
  directives: Record<string, string[]> | null;
}

